:root {
  --bg: #f3f6fa;
  --panel: #ffffff;
  --panel-soft: #f8fbff;
  --navy: #06192f;
  --navy-2: #0b2343;
  --navy-3: #102d52;
  --blue: #132178;
  --blue-2: #0a64d8;
  --cyan: #32c5ff;
  --steel: #617086;
  --muted: #8794a8;
  --line: #dbe4ef;
  --line-strong: #c5d2e3;
  --green: #12805c;
  --green-bg: #e7f7f0;
  --amber: #a86105;
  --amber-bg: #fff3db;
  --red: #b42318;
  --red-bg: #ffe9e6;
  --shadow: 0 18px 48px rgba(12, 33, 61, 0.12);
  --shadow-soft: 0 12px 30px rgba(12, 33, 61, 0.08);
  font-family: Inter, "Segoe UI", Arial, "Microsoft YaHei", sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
}

body {
  margin: 0;
  color: #152033;
  background:
    radial-gradient(circle at 18% 8%, rgba(19, 33, 120, 0.08), transparent 30%),
    linear-gradient(135deg, #f6f8fb 0%, #eef3f8 100%);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  border: 0;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  color: #17243a;
  outline: none;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

input,
select {
  height: 40px;
  padding: 0 12px;
}

textarea {
  min-height: 92px;
  padding: 12px;
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(19, 33, 120, 0.75);
  box-shadow: 0 0 0 3px rgba(19, 33, 120, 0.14);
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 780px;
}

th,
td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: middle;
}

th {
  color: #526075;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  background: #f7f9fc;
}

td {
  font-size: 14px;
  color: #263348;
}

tbody tr {
  transition: background 160ms ease;
}

tbody tr:hover {
  background: #f6faff;
}

tbody tr.selected {
  background: #edf6ff;
}

.login-page {
  position: relative;
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 460px;
  align-items: center;
  gap: 46px;
  overflow: hidden;
  padding: 54px clamp(28px, 6vw, 96px);
  isolation: isolate;
}

.login-page::before {
  position: absolute;
  inset: 0;
  z-index: -2;
  content: "";
  background:
    linear-gradient(90deg, rgba(5, 20, 39, 0.96) 0%, rgba(7, 26, 49, 0.86) 42%, rgba(7, 26, 49, 0.34) 72%, rgba(7, 26, 49, 0.72) 100%),
    url("data:image/png;base64,") center / cover no-repeat;
}

.login-page::after {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: "";
  background:
    linear-gradient(rgba(255, 255, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.035) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(90deg, #000 0%, rgba(0, 0, 0, 0.65) 52%, transparent 100%);
}

.login-brand-panel {
  max-width: 780px;
  color: #fff;
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.brand-lockup.large {
  margin-bottom: 86px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 8px;
  color: #fff;
  background:
    linear-gradient(135deg, rgba(19, 33, 120, 0.95), rgba(50, 197, 255, 0.72)),
    var(--navy);
  font-size: 14px;
  font-weight: 800;
  box-shadow: 0 12px 26px rgba(19, 33, 120, 0.25);
  overflow: hidden;
}

/* When the brand mark is the chatbot avatar image, fill the square cleanly. */
img.brand-mark {
  object-fit: cover;
  padding: 0;
}

.brand-lockup.large img.brand-mark {
  width: 56px;
  height: 56px;
}

.brand-lockup strong {
  display: block;
  font-size: 18px;
  letter-spacing: 0.08em;
}

.brand-lockup small {
  display: block;
  color: rgba(255, 255, 255, 0.68);
  font-size: 12px;
  margin-top: 2px;
}

.eyebrow {
  margin: 0 0 10px;
  color: var(--blue);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.login-copy h1 {
  margin: 0;
  max-width: 760px;
  font-size: clamp(42px, 6vw, 76px);
  line-height: 0.98;
  font-weight: 800;
}

.login-copy p:last-child {
  max-width: 640px;
  margin: 24px 0 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: 17px;
  line-height: 1.7;
}

.login-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  max-width: 620px;
  margin-top: 46px;
}

.login-stats div {
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  padding: 18px;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
}

.login-stats strong {
  display: block;
  font-size: 27px;
}

.login-stats span {
  display: block;
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.66);
  font-size: 12px;
}

.login-card {
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.32);
  border-radius: 8px;
  padding: 34px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(18px);
}

.login-card-header h2 {
  margin: 18px 0 8px;
  color: #0b1f3b;
  font-size: 32px;
}

.login-card-header p {
  margin: 0 0 28px;
  color: var(--steel);
  line-height: 1.6;
}

.system-chip {
  display: inline-flex;
  align-items: center;
  height: 26px;
  padding: 0 10px;
  border: 1px solid #cfe2ff;
  border-radius: 999px;
  color: var(--blue-2);
  background: #eef6ff;
  font-size: 12px;
  font-weight: 700;
}

.form-stack {
  display: grid;
  gap: 16px;
}

.form-stack label,
.form-grid label {
  display: grid;
  gap: 7px;
  color: #3b475a;
  font-size: 13px;
  font-weight: 700;
}

.password-field {
  position: relative;
  display: block;
}

.password-field input {
  width: 100%;
  padding-right: 64px;
}

.password-toggle {
  position: absolute;
  top: 50%;
  right: 8px;
  transform: translateY(-50%);
  padding: 4px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--blue-2);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.password-toggle:hover {
  background: rgba(19, 33, 120, 0.1);
}

.login-footnote {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-top: 22px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.login-footnote span {
  width: 7px;
  height: 7px;
  margin-top: 5px;
  border-radius: 999px;
  background: var(--green);
}

.primary-button,
.secondary-button,
.ghost-button,
.text-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  border-radius: 6px;
  padding: 0 14px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease, color 160ms ease;
}

.primary-button {
  color: #fff;
  background: linear-gradient(135deg, var(--blue-2), var(--blue));
  box-shadow: 0 10px 22px rgba(19, 33, 120, 0.2);
}

.secondary-button {
  border: 1px solid var(--line-strong);
  color: #15304f;
  background: #fff;
}

.ghost-button {
  border: 1px solid rgba(21, 48, 79, 0.12);
  color: #30435e;
  background: #f7f9fc;
}

.text-button {
  min-height: auto;
  padding: 0;
  color: var(--blue-2);
  background: transparent;
  box-shadow: none;
}

.primary-button:hover,
.secondary-button:hover,
.ghost-button:hover {
  transform: translateY(-1px);
}

.full {
  width: 100%;
}

.app-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 282px minmax(0, 1fr);
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 22px;
  overflow-y: auto;
  padding: 22px 16px;
  color: #fff;
  background:
    linear-gradient(180deg, rgba(9, 33, 63, 0.96), rgba(4, 17, 32, 0.98)),
    radial-gradient(circle at 70% 0%, rgba(19, 33, 120, 0.24), transparent 32%);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.nav-list {
  display: grid;
  gap: 4px;
}

.nav-item {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  width: 100%;
  padding: 10px 10px;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.78);
  background: transparent;
  text-align: left;
  cursor: grab;
}

.nav-item.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.nav-item.drag-over {
  box-shadow: inset 0 2px 0 0 var(--cyan);
}

.nav-badge {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--blue);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
}

.nav-item:hover,
.nav-item.active {
  color: #fff;
  background: rgba(255, 255, 255, 0.09);
}

.nav-item.active {
  box-shadow: inset 0 0 0 1px rgba(50, 197, 255, 0.2);
}

.nav-indicator {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.28);
}

.nav-item.active .nav-indicator {
  background: var(--cyan);
  box-shadow: 0 0 0 5px rgba(50, 197, 255, 0.12);
}

.nav-item strong {
  display: block;
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-item small {
  display: block;
  margin-top: 2px;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.5);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-status {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: auto;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.07);
}

.sidebar-status strong,
.sidebar-status small {
  display: block;
}

.sidebar-status small {
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.58);
}

.status-light {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #3be28f;
  box-shadow: 0 0 0 5px rgba(59, 226, 143, 0.14);
}

.sidebar-backdrop {
  display: none;
}

.workspace {
  min-width: 0;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(160px, auto) minmax(200px, 1fr) auto auto auto;
  gap: 14px;
  align-items: center;
  min-height: 72px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(14px);
}

.login-language {
  position: absolute;
  top: 28px;
  right: 32px;
  z-index: 5;
}

.language-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  border: 1px solid rgba(19, 33, 120, 0.28);
  border-radius: 3px;
  padding: 0 10px;
  color: #15304f;
  background: rgba(255, 255, 255, 0.94);
  cursor: pointer;
  font-size: 12px;
  font-weight: 900;
  box-shadow: 0 8px 18px rgba(12, 33, 61, 0.08);
}

.language-switch span {
  display: grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  border-radius: 2px;
  color: #fff;
  background: var(--navy-2);
  font-size: 11px;
}

.language-switch.on-login {
  color: #fff;
  background: rgba(7, 26, 49, 0.58);
  border-color: rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(12px);
}

.language-switch.on-login span {
  background: var(--blue);
}

.topbar > div:first-of-type strong {
  display: block;
  color: #132843;
  font-size: 16px;
}

.topbar > div:first-of-type span {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.search-box {
  position: relative;
  display: block;
}

.search-box span {
  position: absolute;
  top: 50%;
  left: 13px;
  width: 12px;
  height: 12px;
  border: 2px solid #7f8da2;
  border-radius: 50%;
  transform: translateY(-50%);
}

.search-box span::after {
  position: absolute;
  right: -6px;
  bottom: -4px;
  width: 7px;
  height: 2px;
  border-radius: 999px;
  background: #7f8da2;
  content: "";
  transform: rotate(45deg);
}

.search-box input {
  padding-left: 36px;
  background: #f7f9fc;
}

mark.page-find-hit {
  padding: 0 1px;
  border-radius: 2px;
  background: #ffe9a8;
  color: inherit;
}

mark.page-find-hit.current {
  background: #ffc14d;
  box-shadow: 0 0 0 2px rgba(255, 153, 0, 0.45);
}

.icon-button {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
}

.icon-button.mobile-only {
  display: none;
}

.icon-button.mobile-only span {
  width: 17px;
  height: 2px;
  margin: 2px 0;
  border-radius: 999px;
  background: #213852;
}

.bell-dot {
  width: 13px;
  height: 16px;
  border: 2px solid #526075;
  border-radius: 8px 8px 5px 5px;
}

.bell-dot::after {
  position: absolute;
  top: 9px;
  right: 10px;
  width: 7px;
  height: 7px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: var(--red);
  content: "";
}

.admin-profile {
  display: flex;
  align-items: center;
  gap: 10px;
}

.admin-profile > span {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 8px;
  color: #fff;
  background: var(--navy-2);
  font-size: 12px;
  font-weight: 800;
}

.admin-profile strong,
.admin-profile small {
  display: block;
}

.admin-profile small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
}

.content-area {
  max-width: 1600px;
  margin: 0 auto;
  padding: 28px;
}

.page-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-end;
  margin-bottom: 22px;
}

.page-header h1 {
  margin: 0;
  color: #0d213c;
  font-size: clamp(26px, 3vw, 36px);
  line-height: 1.15;
}

.page-header p:not(.eyebrow) {
  max-width: 780px;
  margin: 8px 0 0;
  color: var(--steel);
  line-height: 1.55;
}

.page-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.metric-card,
.panel,
.upload-zone,
.review-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow-soft);
}

.metric-card {
  position: relative;
  overflow: hidden;
  min-height: 142px;
  padding: 18px;
}

.metric-card::after {
  position: absolute;
  right: -22px;
  bottom: -30px;
  width: 92px;
  height: 92px;
  border: 1px solid rgba(19, 33, 120, 0.16);
  border-radius: 50%;
  content: "";
}

.metric-card p,
.metric-card small {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.metric-card strong {
  display: block;
  margin-top: 8px;
  color: #0c213e;
  font-size: 30px;
  line-height: 1;
}

.metric-card small {
  display: block;
  margin-top: 18px;
}

.delta {
  position: absolute;
  top: 18px;
  right: 18px;
  display: inline-flex;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.delta.up,
.delta.down {
  color: var(--green);
  background: var(--green-bg);
}

.dashboard-grid,
.analytics-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(320px, 0.8fr);
  gap: 18px;
}

.panel {
  min-width: 0;
  padding: 18px;
}

.panel.wide {
  grid-column: span 1;
}

.panel-header,
.table-toolbar,
.chat-header,
.modal-header,
.review-top {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 16px;
}

.panel h2,
.panel-header h2,
.table-toolbar h2,
.review-card h2 {
  margin: 0;
  color: #102643;
  font-size: 18px;
}

.panel p,
.panel-header p,
.table-toolbar p {
  margin: 5px 0 0;
  color: var(--steel);
  line-height: 1.5;
}

.line-chart {
  display: block;
  width: 100%;
  min-height: 190px;
}

.line-chart .grid-lines line {
  stroke: #dce6f2;
  stroke-dasharray: 5 8;
}

.line-chart circle {
  fill: #fff;
  stroke: var(--blue);
  stroke-width: 3;
}

.line-chart .axis-label {
  fill: #7a8aa0;
  font-size: 11px;
}

.line-chart .axis-caption {
  fill: #46556b;
  font-size: 11px;
  font-weight: 700;
}

.donut-wrap {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

.donut {
  display: grid;
  place-items: center;
  width: 164px;
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, #fff 0 56%, transparent 57%),
    conic-gradient(var(--blue) var(--value), #e7edf5 0);
}

.donut span {
  color: #0f2745;
  font-size: 25px;
  font-weight: 900;
}

.compact-list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.compact-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.compact-list span {
  color: var(--steel);
}

.bar-list {
  display: grid;
  gap: 14px;
}

.bar-row {
  display: grid;
  grid-template-columns: minmax(140px, 1.1fr) minmax(120px, 1fr) 50px;
  gap: 12px;
  align-items: center;
}

.bar-row strong,
.bar-row span {
  display: block;
}

.bar-row strong {
  color: #20324c;
  font-size: 13px;
}

.bar-row span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.bar-row b {
  color: #17304d;
  text-align: right;
}

.bar-track,
.progress {
  height: 12px;
  overflow: hidden;
  border-radius: 999px;
  background: #e7edf5;
}

.bar-track span,
.progress span {
  display: block;
  height: 100%;
  /* Reset: `.bar-row span` sets margin-top:3px (meant for the label caption),
     which otherwise pushes the fill down and leaves a grey gap at the top. */
  margin: 0;
  min-width: 4px;
  /* Square fill: the track's overflow:hidden rounds the outer (left) corners,
     while the right edge stays a clean vertical line. An inherited 999px radius
     would round the fill's right corners and let grey show through the notches. */
  border-radius: 0;
  background: linear-gradient(90deg, var(--blue-2), var(--cyan));
}

/* Pie/donut legend: a colour swatch + label on the left, count on the right.
   Reuses .compact-list (flex, space-between) so it lines up with the donut. */
.legend-list .legend-label {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.legend-dot {
  flex: none;
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.legend-list strong {
  color: #20324c;
  font-size: 13px;
}

/* Compact Bar/Pie switch that sits in the panel header next to the title. */
.segmented.chart-toggle button {
  min-height: 28px;
  padding: 0 10px;
  font-size: 12px;
}

tr.clickable {
  cursor: pointer;
}

tr.clickable:hover td {
  background: #f1f6fd;
}

.risk-item.clickable {
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.risk-item.clickable:hover {
  border-color: var(--blue);
  background: #f5f9ff;
}

.risk-list {
  display: grid;
  gap: 12px;
}

.risk-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
}

.risk-item strong,
.risk-item p {
  margin: 0;
}

.risk-item p {
  margin-top: 5px;
  color: var(--steel);
  line-height: 1.45;
}

.pill {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 24px;
  padding: 4px 9px;
  border-radius: 999px;
  color: #35516f;
  background: #eef2f7;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.pill.live,
.pill.active,
.pill.resolved,
.pill.enabled,
.pill.connected,
.pill.success,
.pill.assigned,
.pill.follow-up,
.pill.hot {
  color: var(--green);
  background: var(--green-bg);
}

.pill.high,
.pill.level-a,
.pill.needs-takeover,
.pill.unresolved,
.pill.engineer-review,
.pill.risk,
.pill.engineer-needed {
  color: var(--red);
  background: var(--red-bg);
}

.pill.medium,
.pill.level-b,
.pill.draft,
.pill.processing,
.pill.pending,
.pill.pending-review,
.pill.sales-needed,
.pill.nurturing,
.pill.warm {
  color: var(--amber);
  background: var(--amber-bg);
}

.pill.disabled,
.pill.level-c {
  color: #59687c;
  background: #edf1f5;
}

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.table-wrap table {
  background: #fff;
}

tr[data-conversation] {
  cursor: pointer;
}

.conversation-shell {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(420px, 0.95fr);
  gap: 18px;
  align-items: start;
}

.filter-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 170px auto;
  gap: 10px;
  margin-bottom: 14px;
}

.chat-panel,
.takeover-chat {
  min-height: 680px;
}

.chat-header h2 {
  margin: 0;
  color: #102643;
}

.chat-header p {
  margin: 6px 0 0;
  color: var(--steel);
}

.customer-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.customer-summary span {
  display: inline-flex;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: #42526a;
  background: #f8fbff;
  font-size: 12px;
}

.chat-stream {
  display: grid;
  gap: 14px;
  max-height: 560px;
  overflow-y: auto;
  padding-right: 4px;
}

.message {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.message.user {
  grid-template-columns: minmax(0, 1fr) 34px;
}

.message.user .message-avatar {
  grid-column: 2;
}

.message.user .message-bubble {
  grid-row: 1;
}

.message-avatar {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  color: #fff;
  background: var(--navy-2);
  font-size: 11px;
  font-weight: 900;
}

.message.ai .message-avatar {
  background: linear-gradient(135deg, var(--blue-2), var(--cyan));
}

.message.admin .message-avatar {
  background: var(--green);
}

.message-bubble {
  padding: 13px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f8fbff;
}

.message.user .message-bubble {
  background: #eef6ff;
}

.message-bubble p {
  margin: 0;
  color: #23324a;
  line-height: 1.58;
}

.answer-meta {
  display: grid;
  gap: 10px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.answer-meta > span {
  color: var(--muted);
  font-size: 12px;
}

.answer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.answer-actions button {
  min-height: 30px;
  border: 1px solid #cfe2ff;
  border-radius: 6px;
  padding: 0 9px;
  color: var(--blue-2);
  background: #fff;
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.product-grid {
  display: grid;
  gap: 14px;
}

.family-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 14px;
}

.family-card {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) 18px;
  gap: 14px;
  align-items: center;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.family-card:hover {
  border-color: var(--blue);
  box-shadow: 0 8px 18px rgba(12, 33, 61, 0.08);
}

.family-card .product-thumb {
  min-height: 64px;
}

.family-card h3 {
  font-size: 15px;
  color: #16304d;
}

.family-card small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
}

.family-chevron {
  color: var(--blue);
  font-size: 22px;
  font-weight: 700;
}

.back-link {
  margin-bottom: 12px;
}

.text-button.danger {
  color: #c0392b;
}

.text-button.danger:hover {
  background: rgba(192, 57, 43, 0.1);
}

.product-item {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
}

.product-thumb {
  display: grid;
  place-items: center;
  min-height: 96px;
  border: 1px solid #cfe2ff;
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(19, 33, 120, 0.14), rgba(50, 197, 255, 0.06)),
    repeating-linear-gradient(45deg, transparent 0 10px, rgba(19, 33, 120, 0.07) 10px 11px);
}

.product-thumb span {
  color: #164f8f;
  font-size: 20px;
  font-weight: 900;
}

.product-body {
  display: grid;
  gap: 14px;
}

.product-body h3 {
  margin: 0;
  color: #102643;
}

.product-body p {
  margin: 5px 0 0;
  color: var(--steel);
}

.product-body dl,
.user-context dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 0;
}

.product-body dt,
.user-context dt {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.product-body dd,
.user-context dd {
  margin: 3px 0 0;
  color: #27354b;
  line-height: 1.4;
}

.item-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.segmented {
  display: inline-flex;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #f7f9fc;
}

.segmented button {
  min-height: 34px;
  padding: 0 12px;
  color: #5a6a80;
  background: transparent;
  cursor: pointer;
  font-weight: 800;
}

.segmented button.active {
  color: #fff;
  background: var(--navy-2);
}

.modal-layer {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: 28px;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 13, 27, 0.55);
}

.modal {
  position: relative;
  width: min(980px, 100%);
  max-height: calc(100vh - 56px);
  overflow-y: auto;
  border-radius: 8px;
  padding: 22px;
  background: #fff;
  box-shadow: var(--shadow);
}

.icon-close {
  width: 36px;
  height: 36px;
  border-radius: 6px;
  color: #263348;
  background: #eef2f7;
  cursor: pointer;
  font-size: 24px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.form-grid.compact {
  margin-top: 18px;
}

.full-field {
  grid-column: 1 / -1;
}

.avatar-field > span,
.full-field > span {
  display: block;
  margin-bottom: 7px;
  color: #3b475a;
  font-size: 13px;
  font-weight: 700;
}

.form-grid .avatar-drop {
  display: flex;
  gap: 16px;
  align-items: center;
  padding: 16px;
  border: 1.5px dashed #b9cde8;
  border-radius: 10px;
  background: #f8fbff;
  cursor: pointer;
}

.form-grid .avatar-drop:hover {
  border-color: var(--blue);
}

.avatar-preview {
  width: 64px;
  height: 64px;
  border-radius: 12px;
  object-fit: cover;
  border: 1px solid var(--line);
  background: #fff;
}

.avatar-drop-copy strong {
  display: block;
  color: #1b3350;
  font-size: 13px;
}

.avatar-drop-copy small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
}

.language-toggle-list {
  display: grid;
  gap: 8px;
}

.language-toggle-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
  font-size: 13px;
  color: #20324c;
}

.modal-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 10px;
}

.knowledge-layout,
.faq-layout,
.settings-layout,
.takeover-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 18px;
  align-items: start;
  margin-bottom: 18px;
}

.upload-zone {
  min-height: 260px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  padding: 30px;
  text-align: center;
  background:
    linear-gradient(135deg, rgba(19, 33, 120, 0.08), rgba(50, 197, 255, 0.03)),
    #fff;
  border-style: dashed;
}

.upload-zone h2,
.upload-zone p {
  margin: 0;
}

.upload-zone p {
  max-width: 520px;
  color: var(--steel);
  line-height: 1.6;
}

.upload-icon {
  width: 56px;
  height: 56px;
  border: 2px solid #b8d8ff;
  border-radius: 8px;
  background:
    linear-gradient(180deg, transparent 44%, rgba(19, 33, 120, 0.14) 44%),
    #fff;
}

.test-box,
.reply-box {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
}

.retrieval-result {
  margin-top: 14px;
  padding: 13px;
  border: 1px solid #cfe2ff;
  border-radius: 8px;
  background: #f5faff;
}

.retrieval-result p {
  margin: 6px 0 0;
}

.form-panel h2 {
  margin-top: 0;
}

.inline-check {
  display: flex;
  gap: 9px;
  align-items: center;
  color: #3b475a;
  font-size: 13px;
  font-weight: 800;
}

.inline-check input {
  width: 16px;
  height: 16px;
}

.toggle {
  display: inline-flex;
  width: 44px;
  height: 26px;
  border-radius: 999px;
  background: #cbd5e1;
  padding: 3px;
  border: none;
  box-sizing: border-box;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  align-items: center;
  transition: background 160ms ease;
}

.toggle::before {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  /* Soft shadow so the round knob lifts off the pill track. */
  box-shadow: 0 1px 2px rgba(15, 39, 69, 0.25);
  content: "";
  transition: transform 160ms ease;
}

.toggle.on {
  background: var(--blue);
}

.toggle.on::before {
  /* track width - knob width - 2*padding = 44 - 20 - 6 */
  transform: translateX(18px);
}

.settings-hero {
  display: flex;
  gap: 16px;
  align-items: center;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.agent-avatar {
  display: grid;
  place-items: center;
  width: 76px;
  height: 76px;
  border: 1px solid #b9dcff;
  border-radius: 8px;
  color: #fff;
  background:
    linear-gradient(135deg, rgba(19, 33, 120, 0.98), rgba(50, 197, 255, 0.72)),
    var(--navy);
  font-size: 22px;
  font-weight: 900;
}

.settings-hero h2,
.settings-hero p {
  margin: 0;
}

.settings-hero p {
  margin-top: 6px;
  color: var(--steel);
  line-height: 1.5;
}

.control-list,
.integration-list {
  display: grid;
  gap: 12px;
}

.control-item,
.integration-item {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
}

.control-item p,
.integration-item p {
  margin: 5px 0 0;
  color: var(--steel);
  line-height: 1.45;
}

.wide-cell {
  min-width: 280px;
  line-height: 1.5;
}

.analytics-cards {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.review-list {
  display: grid;
  gap: 16px;
}

.review-card {
  padding: 18px;
}

.review-id {
  display: inline-flex;
  margin-bottom: 8px;
  color: var(--blue-2);
  font-size: 12px;
  font-weight: 900;
}

.review-columns {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: 14px;
}

.review-columns > div {
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfdff;
}

.review-columns h3,
.review-columns p {
  margin: 0;
}

.review-columns p {
  margin-top: 8px;
  color: #263348;
  line-height: 1.6;
}

.review-columns small {
  display: block;
  margin-top: 12px;
  color: var(--muted);
}

.review-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 14px;
}

.takeover-layout {
  grid-template-columns: 320px minmax(0, 1fr) 340px;
}

.session-list,
.user-context {
  min-height: 680px;
}

.session-item {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
  width: 100%;
  margin-bottom: 10px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.session-item.active,
.session-item:hover {
  border-color: #b9dcff;
  background: #f4f9ff;
}

.session-item strong,
.session-item p,
.session-item small {
  display: block;
  margin: 0;
}

.session-item p {
  margin-top: 4px;
  color: var(--steel);
}

.session-item small {
  margin-top: 5px;
  color: var(--muted);
}

.priority-line {
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  border-radius: 8px 0 0 8px;
  background: var(--amber);
}

.priority-line.high {
  background: var(--red);
}

.chat-stream.takeover {
  max-height: 500px;
}

.reply-box {
  margin-top: 16px;
}

.user-context h2 {
  margin: 0 0 12px;
}

.user-context dl {
  grid-template-columns: 1fr;
  margin-bottom: 20px;
}

.user-context textarea {
  min-height: 170px;
  margin-bottom: 12px;
}

.role-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.role-card {
  display: grid;
  gap: 12px;
}

.role-card h2,
.role-card p {
  margin: 0;
}

.role-card strong {
  color: var(--blue-2);
  font-size: 24px;
}

.toast {
  position: fixed;
  right: 26px;
  bottom: 26px;
  z-index: 100;
  max-width: min(420px, calc(100vw - 40px));
  border: 1px solid #b9dcff;
  border-radius: 8px;
  padding: 13px 16px;
  color: #0b315c;
  background: #f4f9ff;
  box-shadow: var(--shadow);
  font-weight: 800;
}

/* Squared industrial refinement */
input,
select,
textarea,
.brand-mark,
.login-stats div,
.login-card,
.system-chip,
.primary-button,
.secondary-button,
.ghost-button,
.icon-button,
.admin-profile > span,
.nav-item,
.sidebar-status,
.metric-card,
.panel,
.upload-zone,
.review-card,
.risk-item,
.pill,
.delta,
.table-wrap,
.message-avatar,
.message-bubble,
.product-item,
.product-thumb,
.segmented,
.modal,
.icon-close,
.retrieval-result,
.control-item,
.integration-item,
.session-item,
.toast,
.language-switch {
  border-radius: 3px;
}

.language-switch span,
.nav-indicator,
.status-light {
  border-radius: 2px;
}

/* The sliding on/off switch stays fully round despite the squared theme above:
   a pill track with a circular knob. */
.toggle {
  border-radius: 999px;
}

.toggle::before {
  border-radius: 50%;
}

.metric-card::after {
  border-radius: 3px;
  transform: rotate(12deg);
}

.primary-button,
.secondary-button,
.ghost-button {
  box-shadow: none;
}

.primary-button:hover,
.secondary-button:hover,
.ghost-button:hover {
  transform: none;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.18);
}

@media (min-width: 1280px) {
  .dashboard-grid .panel.wide:first-child,
  .analytics-grid .panel.wide:first-child {
    grid-column: span 1;
  }
}

@media (max-width: 1280px) {
  .metric-grid,
  .analytics-cards {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .conversation-shell,
  .takeover-layout,
  .knowledge-layout,
  .faq-layout,
  .settings-layout,
  .analytics-grid,
  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .session-list,
  .user-context,
  .chat-panel,
  .takeover-chat {
    min-height: auto;
  }

  .role-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 920px) {
  .login-page {
    grid-template-columns: 1fr;
    gap: 28px;
    padding: 34px 18px;
  }

  .login-brand-panel {
    max-width: none;
  }

  .brand-lockup.large {
    margin-bottom: 46px;
  }

  .login-stats {
    grid-template-columns: 1fr;
  }

  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: fixed;
    z-index: 60;
    width: 286px;
    transform: translateX(-100%);
    transition: transform 180ms ease;
  }

  .sidebar-open .sidebar {
    transform: translateX(0);
  }

  .sidebar-backdrop {
    position: fixed;
    inset: 0;
    z-index: 50;
    display: none;
    background: rgba(4, 13, 27, 0.45);
  }

  .sidebar-open .sidebar-backdrop {
    display: block;
  }

  .topbar {
    grid-template-columns: 42px minmax(0, 1fr) auto;
  }

  .icon-button.mobile-only {
    display: grid;
  }

  .search-box,
  .logout-button,
  .admin-profile {
    display: none;
  }

  .content-area {
    padding: 20px 14px;
  }

  .page-header {
    display: grid;
    align-items: start;
  }

  .page-actions {
    justify-content: flex-start;
  }

  .metric-grid,
  .analytics-cards,
  .role-grid {
    grid-template-columns: 1fr;
  }

  .filter-bar,
  .test-box,
  .reply-box,
  .product-item,
  .donut-wrap,
  .review-columns,
  .form-grid,
  .product-body dl {
    grid-template-columns: 1fr;
  }

  .modal-layer {
    padding: 14px;
  }
}

@media (max-width: 560px) {
  .login-card {
    padding: 24px;
  }

  .login-language {
    top: 16px;
    right: 16px;
  }

  .login-copy h1 {
    font-size: 38px;
  }

  .topbar {
    padding: 12px;
    gap: 8px;
  }

  .panel,
  .review-card,
  .metric-card {
    padding: 14px;
  }

  .table-toolbar,
  .panel-header,
  .chat-header,
  .review-top {
    display: grid;
  }

  .primary-button,
  .secondary-button,
  .ghost-button {
    width: 100%;
  }

  .page-actions,
  .review-actions {
    width: 100%;
  }

  .segmented {
    width: 100%;
  }

  .segmented button {
    flex: 1;
  }
}


/* ---- SPA integration: preview banner + helpers ---- */
.preview-banner {
  margin: 0 0 18px;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid rgba(245, 158, 11, 0.35);
  background: rgba(245, 158, 11, 0.12);
  color: #92600a;
  font-size: 13px;
  font-weight: 600;
}
.warning-banner {
  margin: 0 0 14px;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(220, 38, 38, 0.32);
  background: rgba(220, 38, 38, 0.08);
  color: #9a2a2a;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.45;
}

.user-context .warning-banner {
  margin-bottom: 10px;
}

.table-empty {
  text-align: center;
  color: var(--ink-muted);
  padding: 22px 0;
}
.muted { color: var(--ink-muted); font-size: 13px; }
